#!/usr/bin/env bash
set -euo pipefail

repoRoot="$(cd "$(dirname "$0")/../.." && pwd)"
tempDir="$(mktemp -d)"
trap 'rm -r -- "$tempDir"' EXIT
export GIT_CONFIG_GLOBAL=/dev/null
export GIT_CONFIG_NOSYSTEM=1
export GIT_TERMINAL_PROMPT=0

gh() {
  printf '%s\n' "$*" >> "$GH_LOG"
  case "$1 $2" in
    'pr list')
      if [[ " $* " == *' --state merged '* ]]; then
        printf 'https://github.com/example/repo/pull/1\n'
      elif [[ -n "${TEST_PR-}" ]]; then
        printf '[{"number":42,"url":"https://github.com/example/repo/pull/42"}]\n'
      else
        printf '[]\n'
      fi
      ;;
    'pr create')
      [[ "${FAIL_CREATE-false}" != true ]] || return 1
      printf 'https://github.com/example/repo/pull/42\n'
      ;;
    'pr edit'|'pr close'|'auth setup-git') ;;
    *) printf 'Unexpected gh call: %s\n' "$*" >&2; return 1 ;;
  esac
}
export -f gh

git init --quiet --bare --initial-branch=main "$tempDir/origin.git"
git clone --quiet "$tempDir/origin.git" "$tempDir/seed"
(
  cd "$tempDir/seed"
  printf '{}\n' > package.json
  printf '[tools]\nnode = "22.22.0"\n' > mise.toml
  git add .
  git -c user.name=Fixture -c user.email=fixture@example.com commit --quiet -m Fixture
  git push --quiet origin main
)

runPublisher() {
  local name="$1" version="$2" existing="$3" base="${4-main}"
  git clone --quiet --branch "$base" "$tempDir/origin.git" "$tempDir/$name"
  (
    cd "$tempDir/$name"
    if [[ -n "$version" ]]; then
      printf '[tools]\nnode = "%s"\n' "$version" > mise.toml
    fi
    export BASE_BRANCH="$base" DEFAULT_BRANCH=main UPDATE_BRANCH=automation/tool-versions
    if [[ "$base" != main ]]; then
      UPDATE_BRANCH="automation/tool-versions-for/$base"
    fi
    export UPDATE_TITLE='chore(deps): update tool versions'
    export RUNNER_TEMP="$tempDir"
    export GITHUB_REPOSITORY=example/repo
    GITHUB_SHA="$(git rev-parse HEAD)"
    export GITHUB_SHA
    export GITHUB_OUTPUT="$tempDir/$name.outputs"
    export GH_LOG="$tempDir/$name.log" TEST_PR="$existing"
    bash "$repoRoot/.github/scripts/publishToolVersions.sh"
  ) | tee "$tempDir/$name.stdout"
}

printf '| Tool | Current | Update |\n| --- | --- | --- |\n| Node.js | 22.22.0 | [22.23.4](https://nodejs.org/en/blog/release/v22.23.4) |\n' > "$tempDir/toolchainVersions.md"
printf '\nChecked but unchanged:\n\n- pnpm: 10.34.9\n' >> "$tempDir/toolchainVersions.md"

runPublisher unchanged '' ''
grep -Fx 'update_available=false' "$tempDir/unchanged.outputs"
grep -Fx 'url=' "$tempDir/unchanged.outputs"
grep -F 'No tool updates are needed for main.' "$tempDir/unchanged.stdout"
grep -F 'Existing open PR: none' "$tempDir/unchanged.stdout"
if grep -Eq '^pr (create|edit|close)' "$tempDir/unchanged.log"; then
  printf 'Unexpected PR mutation when no update is available\n' >&2
  exit 1
fi

runPublisher create 22.23.4 ''
grep -Fx 'needs_push=true' "$tempDir/create.outputs"
grep -Fx 'url=https://github.com/example/repo/pull/42' "$tempDir/create.outputs"
grep -F -- '--label maintenance' "$tempDir/create.log"
grep -F 'Branch automation/tool-versions does not exist yet.' "$tempDir/create.stdout"
grep -F 'Created PR against main: https://github.com/example/repo/pull/42' "$tempDir/create.stdout"
expectedNotice="**Automatically generated by the [Update tool versions workflow.](https://github.com/example/repo/blob/$(git -C "$tempDir/create" rev-parse HEAD^)/.github/workflows/updateToolVersions.md)**"
[[ "$(head -n 1 "$tempDir/toolchainUpdate.md")" == "$expectedNotice" ]]
grep -Fx '## Summary of changes' "$tempDir/toolchainUpdate.md"
grep -Fx '| Tool | Current | Update |' "$tempDir/toolchainUpdate.md"
if grep -Fq 'Test run:' "$tempDir/toolchainUpdate.md"; then
  printf 'Default-branch PR must not be marked as a test\n' >&2
  exit 1
fi
grep -Fx '| Node.js | 22.22.0 | [22.23.4](https://nodejs.org/en/blog/release/v22.23.4) |' "$tempDir/toolchainUpdate.md"
grep -F 'Previous toolchain update: https://github.com/example/repo/pull/1' "$tempDir/toolchainUpdate.md"
[[ "$(tail -n 1 "$tempDir/toolchainUpdate.md")" == '- pnpm: 10.34.9' ]]
branchSha="$(git --git-dir="$tempDir/origin.git" rev-parse automation/tool-versions)"
[[ "$(git --git-dir="$tempDir/origin.git" show -s --format=%an automation/tool-versions)" == 'update-tool-versions automation' ]]

runPublisher refresh 22.23.4 42
grep -Fx 'needs_push=false' "$tempDir/refresh.outputs"
grep -F 'pr edit 42' "$tempDir/refresh.log"
grep -F 'no commit or push is needed.' "$tempDir/refresh.stdout"
grep -F 'Refreshed PR: https://github.com/example/repo/pull/42' "$tempDir/refresh.stdout"
[[ "$(git --git-dir="$tempDir/origin.git" rev-parse automation/tool-versions)" == "$branchSha" ]]

runPublisher recreate 22.23.4 ''
grep -Fx 'needs_push=false' "$tempDir/recreate.outputs"
grep -F 'pr create' "$tempDir/recreate.log"

(
  cd "$tempDir/seed"
  printf 'Updated publication script or documentation\n' > unrelated.txt
  printf '{"description":"Unrelated package metadata change"}\n' > package.json
  git add unrelated.txt package.json
  git -c user.name=Fixture -c user.email=fixture@example.com commit --quiet -m 'Unrelated base branch change'
  git push --quiet origin main
)
runPublisher baseChanged 22.23.4 42
grep -Fx 'needs_push=false' "$tempDir/baseChanged.outputs"
grep -F 'pr edit 42' "$tempDir/baseChanged.log"
[[ "$(git --git-dir="$tempDir/origin.git" rev-parse automation/tool-versions)" == "$branchSha" ]]
if grep -Fq 'auth setup-git' "$tempDir/baseChanged.log"; then
  printf 'Unrelated base branch changes must not trigger a push\n' >&2
  exit 1
fi

runPublisher update 22.24.0 42
grep -Fx 'needs_push=true' "$tempDir/update.outputs"
[[ "$(git --git-dir="$tempDir/origin.git" rev-parse automation/tool-versions)" != "$branchSha" ]]
[[ "$(git --git-dir="$tempDir/origin.git" show automation/tool-versions:unrelated.txt)" == 'Updated publication script or documentation' ]]
[[ "$(git --git-dir="$tempDir/origin.git" show automation/tool-versions:package.json)" == '{"description":"Unrelated package metadata change"}' ]]

runPublisher obsolete '' 42
grep -F 'pr close 42' "$tempDir/obsolete.log"
grep -F 'Closed obsolete PR: https://github.com/example/repo/pull/42' "$tempDir/obsolete.stdout"
grep -Fx 'url=https://github.com/example/repo/pull/42' "$tempDir/obsolete.outputs"

if FAIL_CREATE=true runPublisher failure 22.24.0 ''; then
  printf 'Expected PR creation failure to fail publication\n' >&2
  exit 1
fi
[[ ! -e "$tempDir/failure.outputs" ]]

git -C "$tempDir/seed" push --quiet origin main:refs/heads/feature/test-tools
runPublisher testBranch 22.24.0 '' feature/test-tools
grep -F -- '--title [TEST: feature/test-tools] chore(deps): update tool versions' "$tempDir/testBranch.log"
grep -Fx '> **Test run:** This PR targets **feature/test-tools**, not the default branch **main**.' "$tempDir/toolchainUpdate.md"
runPublisher refreshTestBranch 22.24.0 42 feature/test-tools
grep -F 'pr edit 42 --title [TEST: feature/test-tools]' "$tempDir/refreshTestBranch.log"
printf 'Toolchain publication tests passed\n'
